+// The Minoan look (MinoanKit): ships' hulls, their insides, the stations'
+// bays - one material for a whole model, each face's part of it by its vertex
+// colour's red channel (zone = round(r * 16)):
+//   0 cream paint   1 red paint   2 dark metal   3 bright steel   4 amber lamp
+//   5 a screen (blue, its UV a radar)   6 the triskelion roundel (UV: the disc)
+//   7 the bull banner (UV: the cloth)   8 cream leather   9 red cloth (green
+//   channel 1: a carpet's meander border)   10 leaves   11 hazard stripes
+// Painted metal worn by use: panel seams on a grid, grime, chips down to the
+// bare steel, streaks; less of it all inside (`wear`). Both sides drawn: a
+// hull's inner face (seen through an open door, a window) is dark bare metal.
+// `zone_override` >= 0: every face that zone (other builders' meshes, no colours).
+shader_type spatial;
+render_mode cull_disabled;
+
+uniform sampler3D noise_tex : filter_linear, repeat_enable;
+uniform vec3 cream : source_color = vec3(0.80, 0.74, 0.62);
+uniform vec3 red : source_color = vec3(0.46, 0.08, 0.06);
+uniform vec3 iron : source_color = vec3(0.20, 0.20, 0.21);
+uniform vec3 steel : source_color = vec3(0.62, 0.61, 0.60);
+uniform vec3 amber : source_color = vec3(1.0, 0.58, 0.2);
+uniform vec3 screen : source_color = vec3(0.25, 0.65, 1.0);
+uniform float wear = 1.0;
+uniform float inside = 0.0;         // (1: no mirror metal - nothing to mirror in a closed room)
+uniform float zone_override = -1.0;
+uniform float panel = 2.2;          // m between seams
+uniform float glow = 1.0;
+
+varying vec3 v_obj;
+varying vec3 v_nrm;
+varying vec4 v_col;
+
+void vertex() {
+	v_obj = VERTEX;
+	v_nrm = NORMAL;
+	v_col = COLOR;
+}
+
+float n3(vec3 p) {
+	return texture(noise_tex, p).r;
+}
+
+// Seams on a grid across the face's main plane (0 on a seam .. 1).
+float seams(vec3 p, vec3 n) {
+	vec3 a = abs(n);
+	vec2 q = a.x > a.y && a.x > a.z ? p.zy : (a.y > a.z ? p.xz : p.xy);
+	q /= panel;
+	q.y *= 1.6;
+	vec2 f = abs(fract(q + 0.5) - 0.5) * panel;
+	float d = min(f.x, f.y / 1.6);
+	float far = smoothstep(0.01, 0.05, fwidth(q.x * panel));   // (too small to see: no seam - nor its shimmer)
+	return mix(smoothstep(0.012, 0.035, d), 1.0, far);
+}
+
+// The triskelion: three spirals round the middle of a red disc, a cream ring at its rim.
+float triskelion(vec2 p) {
+	float r0 = length(p);
+	float ink = smoothstep(0.84, 0.86, r0) * (1.0 - smoothstep(0.93, 0.95, r0));
+	float best = 9.0;
+	vec2 bq = vec2(0.0);
+	for (int k = 0; k < 3; k++) {
+		float a = 1.5708 + float(k) * 2.0944;
+		vec2 c = vec2(cos(a), sin(a)) * 0.33;
+		vec2 q = p - c;
+		float d = length(q);
+		if (d < best) { best = d; bq = q; }
+	}
+	if (best < 0.3) {
+		float a = atan(bq.y, bq.x);
+		float t = (best / 0.075 - a / 6.2832);
+		float line = abs(fract(t) - 0.5);
